-- =======================================================================
-- V300153：按 FinvQuantDesign/Mapping/finv_futu_query_stat.json 补录证券初始数据（需求 11069）
--
-- 来源：FinvQuantDesign/Mapping/finv_futu_query_stat.json（480 行，富途查询统计快照：
--   usc / stock_id / stock_code / name / market_label / market_type / instrument_type / currency ...）
-- 对照：上游 public.finv_quote_secu_meta 补齐 market_code / instrument / sub_instrument_type / name_en
--   （按 usc 命中 226 行，其余 254 行按本地既有口径派生，见下「字段口径」）
--
-- 现状（迁移前实测）：
--   · public.finv_security：480 个 usc 一个都没有  → 本迁移补 480 行
--   · futu.finv_futu_quote_collect：480 个 usc 里 6 个已存在（AENT / BUFC / SH.689009 / TAXX / UL / ULBI）
--     → 其余 474 个中，252 个完全没登记，补 252 行；
--       222 个已按「占位 usc = {market_label}.{futu_symbol}」形式存在（如 HK.01688，stock_id 与来源一致），
--       被唯一约束 (market_code, futu_symbol) 挡住，**本迁移不插入也不改动它们**（usc 归一化另案处理）。
--
-- 字段口径（对齐库里既有行的主导写法）：
--   finv_security：exchange_code HK 21 / SZ 12 / SH 11 / BJ 13 / US 30；
--     market_code HK 1201（人民币柜台 1205）/ HK GEM 1202 / SZ 1120（创业板 1121）/
--       SH 1110（科创板 1112）/ BJ 1130 / US 1315；
--     security_type 3→Stock、4→ETF、12→Stock；type_secu_sub = {security_type}.{market_label}；
--     security_code = 来源 stock_code；security_name(_full) = 上游 name_en 缺则用 name；
--     security_name_cn = name；currency_type = 来源 currency（缺失按市场：HK HKD / 其余 CNY / US USD）；
--     init_date 20000000、provider 'FTMM'、timezone/tz：港澳台沪深 +08:00 / Asia/Shanghai、US -04:00 / America/New_York；
--     flag_enable '1'（新增即启用）。
--   futu.finv_futu_quote_collect：market_type 取来源；market_code（富途码）HK 1（GEM 08xxxx 为 2）/
--     SZ 31（30xxxx 为 35）/ SH 30（688xxx 为 32）/ BJ 38 / US 11；
--     instrument_type、sub_instrument_type 取上游（缺失按 3→3002、4→4002）；instrument 取上游（缺失 3→stock、4→etf）；
--     futu_symbol = stock_code（ftmm_symbol 为生成列，不写入）；req_section NULL；flag_enable '1'；remark 标注数据来源。
--
-- 幂等：INSERT ... ON CONFLICT DO NOTHING（finv_security 主键 usc / 唯一 (exchange_code, security_code)；
--   quote_collect 主键 usc / 唯一 (market_code, futu_symbol)），重复执行不覆盖已有行。
-- 迁移策略：单事务；末尾校验 480 个 usc 均已在 finv_security 出现。
-- =======================================================================

BEGIN;

-- ---- 1) public.finv_security：480 行 ----

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- ---- 2) futu.finv_futu_quote_collect：252 行（222 行占位 usc 已存在，跳过）----

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

DO $$
DECLARE
    v_sec bigint;
    v_qc  bigint;
BEGIN
    SELECT count(*) INTO v_sec FROM public.finv_security WHERE remark = 'finv_futu_query_stat';
    SELECT count(*) INTO v_qc  FROM futu.finv_futu_quote_collect WHERE remark = 'finv_futu_query_stat';
    IF v_sec <> 480 THEN
        RAISE EXCEPTION 'V300153 校验失败：finv_security 应有 480 行来源标记数据，实际 % 行', v_sec;
    END IF;
    IF v_qc <> 252 THEN
        RAISE EXCEPTION 'V300153 校验失败：finv_futu_quote_collect 应有 252 行来源标记数据，实际 % 行', v_qc;
    END IF;
    RAISE NOTICE 'V300153：finv_security 补 480 行、quote_collect 补 252 行（另 222 行占位 usc 已存在，未动）';
END $$;

COMMIT;
